<script setup>
import AccountPageHeader from '@/Components/Account/AccountPageHeader.vue';
import { ref } from 'vue';
import { Head, Link, useForm, usePage } from '@inertiajs/vue3';
import axios from 'axios';
import BrowserDraftNotice from '@/Components/BrowserDraftNotice.vue';
import AddressCityField from '@/Components/AddressCityField.vue';
import { useBrowserDraft } from '@/composables/useBrowserDraft.mjs';
import Layout from '@/Layouts/ProviderLayout.vue';
import DiscoveryMap from '@/Components/Marketplace/DiscoveryMap.vue';
const props=defineProps({service:String,listing:Object,types:Array,approved:Boolean});
const form=useForm({title:props.listing?.title||'',description:props.listing?.description||'',type:props.listing?.type||props.types[0],price:props.listing?.price??'',priceUnit:props.listing?.priceUnit||({spaces:'month',haul:'day',raketeer:'job'}[props.service]),status:props.listing?.status||'draft',location:{lat:props.listing?.location.lat??12.0,lng:props.listing?.location.lng??124.75,address:props.listing?.location.address||'',city:props.listing?.location.city||''},photos:props.listing?.photos||[],details:props.listing?.details?.brand?props.listing.details:{brand:'',model:'',year:new Date().getFullYear()},minimumStayMonths:props.listing?.minimumStayMonths??'',contractRules:props.listing?.contractRules??'',driverAvailable:props.listing?.driverAvailable??false});
const page=usePage();
const photoLimit=Math.max(Math.min(page.props.auth?.perks?.listingPhotos??12,12),props.listing?.photos?.length||0);
const {pending,error: draftError,blocked,reloadRequired,changedOnServer,restore,discard,continueWithoutDrafts,complete}=useBrowserDraft({
  userId:()=>page.props.auth?.user?.id,kind:'listing',service:()=>props.service,id:()=>props.listing?.id??'new',
  select:()=>({title:form.title,description:form.description,type:form.type,price:form.price,priceUnit:form.priceUnit,status:form.status,details:{brand:form.details.brand||'',model:form.details.model||'',year:form.details.year??''}}),
  apply:data=>{Object.assign(form,{title:data.title,description:data.description,type:data.type,price:data.price,priceUnit:data.priceUnit,status:data.status});Object.assign(form.details,data.details);},
});
const uploading=ref(false),uploadError=ref('');
function featurePhoto(index){const [photo]=form.photos.splice(index,1);form.photos.unshift(photo);}
function save(){if(uploading.value)return;const url=`/my-listings/${props.service}`;const options={onSuccess:()=>complete()};if(props.listing)form.put(url+'/'+props.listing.id,options);else form.post(url,options);}
async function upload(e){uploadError.value='';const files=Array.from(e.target.files||[]);if(files.length+form.photos.length>photoLimit){uploadError.value=`You can add up to ${photoLimit} photos.${page.props.auth?.perks?.enabled&&!page.props.auth?.user?.aadiPlus?' Aadi Plus members can add more.':''}`;e.target.value='';return;}uploading.value=true;try{for(const photo of files){const data=new FormData();data.append('photo',photo);const response=await axios.post('/listing-photos',data);form.photos.push(response.data.url);}}catch(error){uploadError.value=error.response?.data?.message||'Upload failed. Please try again.';}finally{uploading.value=false;e.target.value='';}}
function locate(){navigator.geolocation?.getCurrentPosition(p=>{form.location.lat=p.coords.latitude;form.location.lng=p.coords.longitude;},()=>uploadError.value='Could not get location. Set the point on the map instead.',{timeout:10000});}
</script>
<template><Layout><Head :title="listing?'Edit listing':'Create listing'"/><main id="provider-main" class="content form-content"><Link href="/my-listings" class="text-button">← My listings</Link><AccountPageHeader :title="listing ? 'Edit listing' : 'Create listing'" description="Add the details, photos, and location people need to choose your listing."/>
<BrowserDraftNotice :pending="pending" :blocked="blocked" :reload-required="reloadRequired" :changed-on-server="changedOnServer" :error="draftError" excluded="location, photos, minimum stay, contract rules and driver availability" @restore="restore" @discard="discard" @continue="continueWithoutDrafts"/>
<div v-if="Object.keys(form.errors).length" role="alert" class="notice error"><p v-for="(error,key) in form.errors" :key="key">{{ error }}</p></div>
<form v-if="!pending && !blocked" @submit.prevent="save" class="listing-form"><section class="form-section"><h2>01 · The essentials</h2><label>Title<input v-model="form.title" required maxlength="255" placeholder="Give your listing a clear, helpful title"/></label><label>Description<textarea v-model="form.description" required rows="5" maxlength="10000" placeholder="What should someone know before they choose this listing?"/></label><div class="field-row"><label>Type<select v-model="form.type"><option v-for="type in types" :value="type">{{ type.replace(/([A-Z])/g,' $1') }}</option></select></label><label>Price (PHP)<input v-model="form.price" type="number" required min="0" max="99999999.99" step="0.01"/></label><label v-if="service==='raketeer'">Per<select v-model="form.priceUnit"><option value="job">Job</option><option value="hour">Hour</option></select></label></div><div v-if="service==='haul'" class="field-row"><label>Brand<input v-model="form.details.brand" required/></label><label>Model<input v-model="form.details.model" required/></label><label>Year<input v-model="form.details.year" type="number" min="1950" :max="new Date().getFullYear()+1" required/></label></div></section>
<section v-if="service==='spaces'" class="form-section"><h2>Rental contract</h2><label>Minimum stay in months (optional)<input v-model="form.minimumStayMonths" type="number" min="1" max="1200" step="1"/></label><label>Additional contract rules (optional)<textarea v-model="form.contractRules" rows="4" maxlength="5000" placeholder="Describe any other rental conditions."></textarea></label></section>
<section v-if="service==='haul'" class="form-section"><h2>Driver availability</h2><label><input v-model="form.driverAvailable" type="checkbox"/> A driver can be requested for this vehicle</label><p>Driver availability and any additional charge are confirmed directly with the customer.</p></section>
<section class="form-section"><h2>02 · Location</h2><p>Choose where this listing appears. For a raket, use the center of the area you serve. Selecting a city does not move the map pin; set the pin or coordinates separately.</p><label v-if="service==='spaces'">Address<input v-model="form.location.address" required maxlength="255" autocomplete="street-address"/></label><div v-else><label for="listing-area">Address / service area</label><AddressCityField id="listing-area" v-model="form.location.address" required area/></div><div v-if="service==='spaces'"><label for="listing-city">City</label><AddressCityField id="listing-city" v-model="form.location.city"/></div><div class="field-row"><label>Latitude<input v-model.number="form.location.lat" type="number" min="-90" max="90" step="any" required/></label><label>Longitude<input v-model.number="form.location.lng" type="number" min="-180" max="180" step="any" required/></label><button type="button" class="button" @click="locate">Use my location</button></div><DiscoveryMap pick :center="[Number(form.location.lat),Number(form.location.lng)]" :listings="[{id:'location',title:'Listing location',price:Number(form.price)||0,location:form.location}]" @pick="([lat,lng])=>{form.location.lat=lat;form.location.lng=lng;}"/></section>
<section class="form-section"><h2>03 · Photos</h2><p>Up to {{ photoLimit }} JPG, PNG, or WebP photos, 5 MB each. Choose one featured photo for search cards and previews. Selecting a featured photo moves it to the front of the gallery.</p><label class="upload">{{ uploading?'Uploading…':'Choose photos' }}<input type="file" accept="image/jpeg,image/png,image/webp" multiple :disabled="uploading" @change="upload"/></label><p v-if="uploadError" role="alert" class="error">{{ uploadError }}</p><p class="photo-editor-count" aria-live="polite">{{ form.photos.length }} / 12 photos · {{ form.photos.length ? 'One featured photo selected' : 'No photos added yet' }}</p><div class="photo-grid"><div v-for="(photo,i) in form.photos" :key="photo" class="photo-editor-item"><img :src="photo" :alt="`Photo ${i+1}`"/><div class="photo-editor-actions"><button type="button" class="button" :aria-pressed="i===0" :disabled="uploading" @click="featurePhoto(i)">{{ i===0 ? 'Featured photo' : 'Set as featured' }}</button><button type="button" class="text-button" :aria-label="`Remove photo ${i+1}`" :disabled="uploading" @click="form.photos.splice(i,1)">Remove</button></div></div></div></section>
<section class="form-section"><h2>04 · Ready when you are</h2><p v-if="!approved">The listing owner must be approved for this role before publication.</p><label>Status<select v-model="form.status"><option value="draft">Draft — only visible to you and administrators</option><option v-if="approved" value="active">Published — visible in search</option><option value="reserved">{{ service==='raketeer'?'Busy':service==='haul'?'Maintenance':'Reserved' }} — hidden from search</option><option v-if="service!=='raketeer'" value="rented">Rented — hidden from search</option><option v-if="service==='spaces'" value="archived">Archived — hidden from search</option></select></label><div class="actions"><button class="button primary" :disabled="form.processing||uploading">{{ form.processing?'Saving…':'Save listing' }}</button><Link href="/my-listings" class="button">Cancel</Link></div></section></form></main></Layout></template>
